@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= dims.w || id.y >= dims.h) { return; }
    let x = id.x;
    let y = id.y;
    let l = select(x - 1u, 0u, x == 0u);
    let r = min(x + 1u, dims.w - 1u);
    let u = select(y - 1u, 0u, y == 0u);
    let d = min(y + 1u, dims.h - 1u);
    let s = 4u * src[y * dims.w + x] + src[y * dims.w + l] + src[y * dims.w + r]
          + src[u * dims.w + x] + src[d * dims.w + x];
    dst[y * dims.w + x] = s / 8u;
}
"""


def read_input(path):
    with open(path) as f:
        tok = f.read().split()
    w, h, steps = int(tok[0]), int(tok[1]), int(tok[2])
    grid = np.array(tok[3:3 + w * h], dtype=np.uint32)
    return w, h, steps, grid


